SELECT a.REGIST_SEQNO registSeqno, a.SEND_STATUS sendStatus, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUBMIT_TIME submitTime, a.CHB_SUBMIT_DEADLINE chbSubmitDeadline, a.SUBMIT_DEADLINE submitDeadline, a.DATA_STATUS dataStatus, a.INSTITUTION_CODE institutionCode, a.PRD_REGIST_CODE prdRegistCode, a.ACCOUNT_NO accountNo, a.ACCOUNT_NAME accountName, a.TRADE_NO tradeNo, a.TRADE_PS tradePs, a.TRADE_COUNTER_ACC_NO tradeCounterAccNo, a.TRADE_COUNTER_ACC_NAME tradeCounterAccName, a.TRADE_COUNTER_ACC_BANK_NAME tradeCounterAccBankName, a.TRADE_COUNTER_ACC_BANK_NO tradeCounterAccBankNo, a.TRADE_CCY tradeCcy, a.TRADE_AMT tradeAmt, a.TRADE_VDATE tradeVdate, a.TRADE_TIME tradeTime, a.POSTSCRIPT postscript, a.REMARK remark, a.UPDATE_TIME FROM CHB_SALER_STL_DEAL_SUB a where 1=1
and a.SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}
and a.SEND_STATUS = #{sendStatus}
#{dataStatus}
and a.CHB_SUBMIT_DEADLINE between STR_TO_DATE(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'%Y-%m-%d') and STR_TO_DATE(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'%Y-%m-%d')
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') >= #{searchStatusDateStart,jdbcType=VARCHAR}
and DATE_FORMAT(a.STATUS_DATE,'%Y-%m-%d') <= #{searchStatusDateEnd,jdbcType=VARCHAR}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') >= #{searchSubmitTimeStart,jdbcType=VARCHAR}
and DATE_FORMAT(a.SUBMIT_TIME,'%Y-%m-%d') <= #{searchSubmitTimeEnd,jdbcType=VARCHAR}
ORDER BY a.UPDATE_TIME DESC

