insert into CHB_SALER_STL_DEAL_SUB ( REGIST_SEQNO,DATA_STATUS, INSTITUTION_CODE, PRD_REGIST_CODE, ACCOUNT_NO, ACCOUNT_NAME, TRADE_NO, TRADE_PS, TRADE_COUNTER_ACC_NO, TRADE_COUNTER_ACC_NAME, TRADE_COUNTER_ACC_BANK_NAME, TRADE_COUNTER_ACC_BANK_NO, TRADE_CCY, TRADE_AMT, TRADE_VDATE, TRADE_TIME, POSTSCRIPT, REMARK,CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE,STATUS_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS,SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG, CREATE_USER,ORG_CODE,CREATE_DEPT,CREATE_TIME,UPDATE_USER, UPDATE_TIME) select HIS_NO,DATA_STATUS, INSTITUTION_CODE, PRD_REGIST_CODE, ACCOUNT_NO, ACCOUNT_NAME, TRADE_NO, TRADE_PS, TRADE_COUNTER_ACC_NO, TRADE_COUNTER_ACC_NAME, TRADE_COUNTER_ACC_BANK_NAME, TRADE_COUNTER_ACC_BANK_NO, TRADE_CCY, TRADE_AMT, TRADE_VDATE, TRADE_TIME, POSTSCRIPT, REMARK,CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE,STATUS_DATE,SUBMIT_TIME,SUMIT_SEQ, SEND_STATUS,SUBMIT_FEEDBACK_STATUS,SUBMIT_FEEDBACK_MSG, CREATE_USER,ORG_CODE,CREATE_DEPT,his.CREATE_TIME,UPDATE_USER, UPDATE_TIME from CHB_SALER_STL_DEAL_SUB_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_SALER_STL_DEAL_SUB_HIS
INSTITUTION_CODE IN
#{regist.institutionCode,jdbcType=VARCHAR}
and TRADE_NO IN
#{regist.tradeNo,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME
INSTITUTION_CODE IN
#{regist.institutionCode,jdbcType=VARCHAR}
and TRADE_NO IN
#{regist.tradeNo,jdbcType=VARCHAR}

mapper.delete:
