INSTITUTION_CODE IN
#{regist.institutionCode,jdbcType=VARCHAR}
and TRADE_NO IN
#{regist.tradeNo,jdbcType=VARCHAR}
)T)
and INSTITUTION_CODE IN
#{regist.institutionCode,jdbcType=VARCHAR}
and TRADE_NO IN
#{regist.tradeNo,jdbcType=VARCHAR}

